def transform(grid):
    out = [row[:] for row in grid]
    period = max(max(row) for row in grid)
    first = grid[1][0] if len(grid) > 1 else grid[0][0]
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value == 0:
                if r == 0:
                    row[c] = (first + c - 2) % period + 1
                else:
                    base = (first + c - 1) % period + 1
                    row[c] = base if c < r else (base - 2) % period + 1
    return out
